            '',
            '',
        ],
    ];


    public function run(): void
    {
        $this->call([
            RoleSeeder::class,
            CommonFailureSeeder::class,
            CommonServiceSeeder::class,
        ]);

        $admin = $this->ensureUser('Administrador', 'admin@aceitera.test', 'password', 'admin');
        $cajero = $this->ensureUser('Cajero', 'cajero@aceitera.test', 'password', 'cajero');

        $supplier = $this->ensureSupplier('Distribuidora Lubricantes GT', 'Carlos Perez', '5555-1234');
        $supplier2 = $this->ensureSupplier('Repuestos y Baterias del Norte', 'Ana Lopez', '5555-9876');

        $categories = $this->ensureCategories();
        $products = $this->ensureProductsWithPhotos($categories, $supplier);
        $this->ensureProductSpecifications($products);

        $customers = $this->ensureCustomers();
        $vehicles = $this->ensureVehicles($customers);
        $mechanics = $this->ensureMechanics();

        if (Purchase::query()->where('invoice_number', 'DEMO-0001')->exists()) {
            $this->command?->info('DemoDataSeeder: el historial de ejemplo ya existe, se omite.');

            return;
        }

        $this->seedPurchases($admin, $products, $supplier, $supplier2);
        $this->seedSalesHistory($admin, $cajero, $products, $customers);
        $this->seedWorkOrders($admin, $mechanics, $vehicles, $products);
        $this->seedQuotes($admin, $products, $customers);
        $this->seedOnlineOrders($products, $customers);
    }

    private function ensureUser(string $name, string $email, string $password, string $role): User
    {
        $user = User::query()->firstOrCreate(
            ['email' => $email],
            [
                'name' => $name,
                'password' => Hash::make($password),
                'email_verified_at' => now(),
            ],
        );

        if (! $user->hasRole($role)) {
            $user->assignRole($role);
        }

        return $user;
    }

    private function ensureSupplier(string $name, string $contact, string $phone): Supplier
    {
        return Supplier::query()->firstOrCreate(
            ['name' => $name],
            ['contact_name' => $contact, 'phone' => $phone, 'active' => true],
        );
    }

    /**
     * @return array<string, Category>
     */
    private function ensureCategories(): array
    {
        $names = ['Aceites y lubricantes', 'Filtros', 'Repuestos'];
        $categories = [];

        foreach ($names as $name) {
            $categories[$name] = Category::query()->firstOrCreate(
                ['slug' => \Illuminate\Support\Str::slug($name)],
                ['name' => $name],
            );
        }

        return $categories;
    }

    /**
     * @param  array<string, Category>  $categories
     * @return array<string, Product>
     */
    private function ensureProductsWithPhotos(array $categories, Supplier $supplier): array
    {
        $definitions = [
            'ACE-15W40-GAL' => ['category' => 'Aceites y lubricantes', 'name' => 'Aceite 15W40 Mineral', 'unit' => 'galon', 'is_bulk' => true, 'cost_price' => 60, 'sale_price' => 95, 'min_stock' => 5, 'current_stock' => 40, 'brand' => 'Genérico'],
            'ACE-20W50-LT' => ['category' => 'Aceites y lubricantes', 'name' => 'Aceite 20W50 para moto', 'unit' => 'litro', 'is_bulk' => true, 'cost_price' => 20, 'sale_price' => 35, 'min_stock' => 10, 'current_stock' => 60, 'brand' => 'Mobil'],
            'FIL-ACE-001' => ['category' => 'Filtros', 'name' => 'Filtro de aceite universal', 'unit' => 'unidad', 'is_bulk' => false, 'cost_price' => 15, 'sale_price' => 28, 'min_stock' => 8, 'current_stock' => 25, 'brand' => 'Bosch'],
            'FIL-AIRE-001' => ['category' => 'Filtros', 'name' => 'Filtro de aire universal', 'unit' => 'unidad', 'is_bulk' => false, 'cost_price' => 25, 'sale_price' => 45, 'min_stock' => 5, 'current_stock' => 18, 'brand' => 'Toyota'],
            'BUJ-STD-001' => ['category' => 'Repuestos', 'name' => 'Bujía estándar', 'unit' => 'unidad', 'is_bulk' => false, 'cost_price' => 12, 'sale_price' => 22, 'min_stock' => 10, 'current_stock' => 50, 'brand' => 'NGK'],
            'BAT-12V-45' => ['category' => 'Repuestos', 'name' => 'Batería 12V 45Ah', 'unit' => 'unidad', 'is_bulk' => false, 'cost_price' => 350, 'sale_price' => 480, 'min_stock' => 2, 'current_stock' => 6, 'brand' => 'Ritar'],
        ];

        $products = [];

        foreach ($definitions as $sku => $data) {
            $product = Product::query()->firstOrCreate(
                ['sku' => $sku],
                [
                    'category_id' => $categories[$data['category']]->id,
                    'name' => $data['name'],
                    'brand' => $data['brand'],
                    'unit' => $data['unit'],
                    'is_bulk' => $data['is_bulk'],
                    'cost_price' => $data['cost_price'],
                    'sale_price' => $data['sale_price'],
                    'min_stock' => $data['min_stock'],
                    'current_stock' => $data['current_stock'],
                    'active' => true,
                ],
            );

            if (! $product->suppliers()->where('supplier_id', $supplier->id)->exists()) {
                $product->suppliers()->attach($supplier->id, ['cost_price' => $data['cost_price']]);
            }

            $this->attachDemoPhoto($product, $sku);

            $products[$sku] = $product;
        }

        return $products;
    }

    /**
     * @param  array<string, Product>  $products
     */
    private function ensureProductSpecifications(array $products): void
    {
        $definitions = [
            'ACE-15W40-GAL' => [
                'Viscosidad' => '15W-40',
                'Tipo' => 'Mineral',
                'Clasificación API' => 'CI-4/SL',
                'Presentación' => 'Galón (3.785 L)',
                'Uso recomendado' => 'Motores diésel y gasolina',
            ],
            'ACE-20W50-LT' => [
                'Viscosidad' => '20W-50',
                'Tipo' => 'Semisintético',
                'Clasificación API' => 'SN',
                'Presentación' => 'Litro',
                'Uso recomendado' => 'Motocicletas 4 tiempos',
            ],
            'FIL-ACE-001' => [
                'Rosca' => '3/4-16 UNF',
                'Altura' => '84 mm',
                'Diámetro' => '76 mm',
                'Válvula anti-retorno' => 'Sí',
                'Compatibilidad' => 'Toyota, Nissan, Mitsubishi (genérico)',
            ],
            'FIL-AIRE-001' => [
                'Tipo' => 'Panel de papel plisado',
                'Largo' => '250 mm',
                'Ancho' => '178 mm',
                'Alto' => '30 mm',
                'Eficiencia de filtrado' => '98%',
            ],
            'BUJ-STD-001' => [
                'Rosca' => 'M14 x 1.25',
                'Separación de electrodo' => '0.8 - 0.9 mm',
                'Tipo de electrodo' => 'Cobre',
                'Alcance' => '19 mm (rosca larga)',
                'Torque recomendado' => '20-25 Nm',
            ],
            'BAT-12V-45' => [
                'Voltaje' => '12V',
                'Capacidad' => '45 Ah',
                'Corriente de arranque (CCA)' => '360 A',
                'Dimensiones' => '207 x 175 x 190 mm',
                'Tipo' => 'Plomo-ácido libre de mantenimiento',
            ],
        ];

        foreach ($definitions as $sku => $specs) {
            $product = $products[$sku] ?? null;

            if (! $product) {
                continue;
            }

            foreach (array_values($specs) as $index => $value) {
                $label = array_keys($specs)[$index];

                \App\Models\ProductSpecification::query()->firstOrCreate(
                    ['product_id' => $product->id, 'label' => $label],
                    ['value' => $value, 'sort_order' => $index],
                );
            }
        }
    }

    private function attachDemoPhoto(Product $product, string $sku): void
    {
        $images = self::PRODUCT_IMAGES[$sku] ?? [];
        $existingCount = $product->images()->count();

        foreach ($images as $index => $base64) {
            // Idempotente: si ya tiene esta foto (por sort_order) la saltamos,
            // asi una corrida posterior solo agrega las fotos que falten.
            if ($index < $existingCount) {
                continue;
            }

            $suffix = $index === 0 ? '' : '-'.($index + 1);
            $path = 'products/demo-'.\Illuminate\Support\Str::slug($sku).$suffix.'.jpg';
            Storage::disk('public')->put($path, base64_decode($base64));

            ProductImage::query()->create([
                'product_id' => $product->id,
                'path' => $path,
                'sort_order' => $index,
            ]);
        }
    }

