    /**
     * @param  \Illuminate\Support\Collection<int, Customer>  $customers
     * @return \Illuminate\Support\Collection<int, CustomerVehicle>
     */
    private function ensureVehicles(\Illuminate\Support\Collection $customers): \Illuminate\Support\Collection
    {
        $definitions = [
            ['plate' => 'P123ABC', 'brand' => 'Toyota', 'model' => 'Corolla', 'year' => 2018, 'color' => 'Gris', 'mileage' => 65000],
            ['plate' => 'P456DEF', 'brand' => 'Honda', 'model' => 'CRV', 'year' => 2020, 'color' => 'Blanco', 'mileage' => 32000],
            ['plate' => 'C789GHI', 'brand' => 'Freightliner', 'model' => 'Cascadia', 'year' => 2015, 'color' => 'Azul', 'mileage' => 210000],
            ['plate' => 'M012JKL', 'brand' => 'Yamaha', 'model' => 'FZ 150', 'year' => 2021, 'color' => 'Negro', 'mileage' => 8000],
        ];

        return collect($definitions)->map(function (array $data, int $index) use ($customers) {
            $customer = $customers[$index % $customers->count()];

            return CustomerVehicle::query()->firstOrCreate(
                ['plate' => $data['plate']],
                [
                    'customer_id' => $customer->id,
                    'brand' => $data['brand'],
                    'model' => $data['model'],
                    'year' => $data['year'],
                    'color' => $data['color'],
                    'mileage' => $data['mileage'],
                ],
            );
        });
    }

