    /**
     * @param  array<string, Product>  $products
     */
    private function seedPurchases(User $admin, array $products, Supplier $supplier, Supplier $supplier2): void
    {
        $service = app(PurchaseService::class);

        // Dos entradas para la MISMA factura (para probar la alerta de
        // "varios registros" en el listado de compras).
        $this->backdatedPurchase($service, $admin, $supplier, [
            ['product_id' => $products['ACE-15W40-GAL']->id, 'quantity' => 20, 'unit_cost' => 61, 'sale_price' => 95],
        ], now()->subDays(12), 'DEMO-0001', 'Entrega parcial de aceite 15W40');

        $this->backdatedPurchase($service, $admin, $supplier, [
            ['product_id' => $products['ACE-20W50-LT']->id, 'quantity' => 24, 'unit_cost' => 19.5],
        ], now()->subDays(12)->addHours(3), 'DEMO-0001', 'Entrega parcial de aceite 20W50 (misma factura)');

        $this->backdatedPurchase($service, $admin, $supplier2, [
            ['product_id' => $products['BAT-12V-45']->id, 'quantity' => 4, 'unit_cost' => 340, 'sale_price' => 475],
            ['product_id' => $products['BUJ-STD-001']->id, 'quantity' => 30, 'unit_cost' => 11.5],
        ], now()->subDays(7), 'DEMO-0002', 'Reposición de baterías y bujías');

        $this->backdatedPurchase($service, $admin, $supplier, [
            ['product_id' => $products['FIL-ACE-001']->id, 'quantity' => 15, 'unit_cost' => 14.8],
            ['product_id' => $products['FIL-AIRE-001']->id, 'quantity' => 12, 'unit_cost' => 24],
        ], now()->subDays(2), 'DEMO-0003', 'Reposición de filtros');
    }

    /**
     * @param  array<int, array{product_id: int, quantity: float, unit_cost: float, sale_price?: float}>  $items
     */
    private function backdatedPurchase(
        PurchaseService $service,
        User $admin,
        Supplier $supplier,
        array $items,
        Carbon $when,
        string $invoiceNumber,
        string $notes,
    ): void {
        $purchase = $service->registerPurchase($admin, $supplier, $items, $when, $invoiceNumber, $notes);

        DB::table('purchases')->where('id', $purchase->id)->update([
            'created_at' => $when,
            'updated_at' => $when,
        ]);

        DB::table('purchase_items')->where('purchase_id', $purchase->id)->update([
            'created_at' => $when,
            'updated_at' => $when,
        ]);

        DB::table('stock_movements')
            ->where('reference_type', Purchase::class)
            ->where('reference_id', $purchase->id)
            ->update(['created_at' => $when, 'updated_at' => $when]);
    }

    /**
     * @param  array<string, Product>  $products
     * @param  \Illuminate\Support\Collection<int, Customer>  $customers
     */
    private function seedSalesHistory(User $admin, User $cajero, array $products, \Illuminate\Support\Collection $customers): void
    {
        $saleService = app(SaleService::class);
        $cashiers = [$admin, $cajero];
        $productList = array_values($products);
        $methods = ['efectivo', 'efectivo', 'efectivo', 'tarjeta', 'transferencia'];

        for ($daysAgo = 10; $daysAgo >= 0; $daysAgo--) {
            $day = Carbon::today()->subDays($daysAgo);

            if ($day->isSunday()) {
                continue;
            }

            $cashier = $cashiers[$daysAgo % 2];
            $openedAt = $day->copy()->setTime(8, 0);

            $session = CashSession::query()->create([
                'user_id' => $cashier->id,
                'opening_amount' => 200,
                'status' => 'open',
                'opened_at' => $openedAt,
            ]);
            DB::table('cash_sessions')->where('id', $session->id)->update([
                'created_at' => $openedAt,
                'updated_at' => $openedAt,
            ]);

            $salesCount = random_int(2, 5);

            for ($i = 0; $i < $salesCount; $i++) {
                $soldAt = $day->copy()->setTime(random_int(8, 18), random_int(0, 59));
                $lineCount = random_int(1, 3);
                $chosen = collect($productList)->random(min($lineCount, count($productList)));

                $items = $chosen->map(fn (Product $product) => [
                    'product_id' => $product->id,
                    'quantity' => in_array($product->unit, ['litro', 'galon'], true) ? random_int(1, 3) : random_int(1, 2),
                ])->values()->all();

                $customer = random_int(1, 100) <= 30 ? $customers->random() : null;
                $total = $chosen->sum(fn (Product $product) => (float) $product->sale_price * ($items[array_search($product->id, array_column($items, 'product_id'))]['quantity'] ?? 0));
                $method = $methods[array_rand($methods)];

                try {
                    $sale = $saleService->createSale(
                        $session->fresh(),
                        $cashier,
                        $customer,
                        $items,
                        [['method' => $method, 'amount' => round($total, 2)]],
                        0,
                    );
                } catch (\Throwable) {
                    continue;
                }

                DB::table('sales')->where('id', $sale->id)->update([
                    'sold_at' => $soldAt, 'created_at' => $soldAt, 'updated_at' => $soldAt,
                ]);
                DB::table('sale_items')->where('sale_id', $sale->id)->update([
                    'created_at' => $soldAt, 'updated_at' => $soldAt,
                ]);
                DB::table('payments')->where('sale_id', $sale->id)->update([
                    'method' => $method, 'created_at' => $soldAt, 'updated_at' => $soldAt,
                ]);
                DB::table('stock_movements')
                    ->where('reference_type', \App\Models\Sale::class)
                    ->where('reference_id', $sale->id)
                    ->update(['created_at' => $soldAt, 'updated_at' => $soldAt]);
            }

            $closedAt = $day->copy()->setTime(19, 0);
            DB::table('cash_sessions')->where('id', $session->id)->update([
                'status' => 'closed',
                'closing_amount' => 200,
                'expected_amount' => 200,
                'difference' => 0,
                'closed_at' => $closedAt,
                'updated_at' => $closedAt,
            ]);
        }
    }

    /**
     * @param  \Illuminate\Support\Collection<int, Mechanic>  $mechanics
     * @param  \Illuminate\Support\Collection<int, CustomerVehicle>  $vehicles
     * @param  array<string, Product>  $products
     */
    private function seedWorkOrders(User $admin, \Illuminate\Support\Collection $mechanics, \Illuminate\Support\Collection $vehicles, array $products): void
    {
        $service = app(WorkOrderService::class);
        $failureIds = CommonFailure::query()->inRandomOrder()->limit(2)->pluck('id')->all();
        $serviceIds = CommonService::query()->inRandomOrder()->limit(2)->pluck('id')->all();

        // 1) Recien recibida.
        $wo1 = $service->createWorkOrder(
            vehicle: $vehicles[0],
            mechanic: $mechanics[0],
            reportedIssue: 'Cliente reporta ruido en el motor al acelerar.',
            mileageIn: (float) $vehicles[0]->mileage,
            notes: 'Ingreso para diagnóstico',
            failureIds: $failureIds,
            type: 'reparacion',
        );
        $this->backdateWorkOrder($wo1, now()->subDays(3));

        // 2) En proceso, con repuestos y mano de obra agregados.
        $wo2 = $service->createWorkOrder(
            vehicle: $vehicles[1],
            mechanic: $mechanics[1],
            reportedIssue: 'Servicio de mantenimiento preventivo.',
            mileageIn: (float) $vehicles[1]->mileage,
            type: 'servicio',
            serviceScope: 'menor',
            serviceIds: $serviceIds,
        );
        $service->addPart($wo2, $products['FIL-ACE-001']->id, 1);
        $service->addPart($wo2, $products['ACE-15W40-GAL']->id, 4);
        $service->addLaborItem($wo2, 'Cambio de aceite y filtro', 75);
        $service->updateStatus($wo2, 'en_proceso');
        $this->backdateWorkOrder($wo2, now()->subDays(2));

        // 3) Lista para entregar.
        $wo3 = $service->createWorkOrder(
            vehicle: $vehicles[2],
            mechanic: $mechanics[0],
            reportedIssue: 'Cambio de batería por falla de arranque.',
            mileageIn: (float) $vehicles[2]->mileage,
            type: 'reparacion',
        );
        $service->addPart($wo3, $products['BAT-12V-45']->id, 1);
        $service->addLaborItem($wo3, 'Instalación de batería', 50);
        $service->updateStatus($wo3, 'en_proceso');
        $service->updateStatus($wo3, 'listo');
        $this->backdateWorkOrder($wo3, now()->subDay());

        // 4) Entregada y facturada (genera una venta de origen "taller").
        $wo4 = $service->createWorkOrder(
            vehicle: $vehicles[3],
            mechanic: $mechanics[1],
            reportedIssue: 'Cambio de bujías por fallo de encendido.',
            mileageIn: (float) $vehicles[3]->mileage,
            type: 'reparacion',
        );
        $service->addPart($wo4, $products['BUJ-STD-001']->id, 4);
        $service->addLaborItem($wo4, 'Cambio de bujías', 40);
        $service->updateStatus($wo4, 'en_proceso');
        $service->updateStatus($wo4, 'listo');

        $session = CashSession::query()->create([
            'user_id' => $admin->id,
            'opening_amount' => 200,
            'status' => 'open',
            'opened_at' => now(),
        ]);

        $wo4 = $service->completeAndBill($wo4, $session, $admin, [
            ['method' => 'efectivo', 'amount' => (float) $wo4->fresh()->total],
        ]);
        DB::table('cash_sessions')->where('id', $session->id)->update([
            'status' => 'closed', 'closing_amount' => 200, 'expected_amount' => 200,
            'difference' => 0, 'closed_at' => now(),
        ]);
        $this->backdateWorkOrder($wo4, now()->subDays(5));
    }

    private function backdateWorkOrder(\App\Models\WorkOrder $workOrder, Carbon $when): void
    {
        DB::table('work_orders')->where('id', $workOrder->id)->update([
            'created_at' => $when, 'updated_at' => $when,
        ]);
    }

    /**
     * @param  array<string, Product>  $products
     * @param  \Illuminate\Support\Collection<int, Customer>  $customers
     */
    private function seedQuotes(User $admin, array $products, \Illuminate\Support\Collection $customers): void
    {
        $service = app(QuoteService::class);

        $service->createQuote(
            $admin,
            $customers[0],
            ['customer_name' => $customers[0]->name, 'customer_phone' => $customers[0]->phone, 'customer_nit' => $customers[0]->nit],
            [
                ['product_id' => $products['ACE-15W40-GAL']->id, 'quantity' => 4],
                ['product_id' => $products['FIL-ACE-001']->id, 'quantity' => 1],
            ],
            8,
            'Cotización de mantenimiento preventivo',
        );

        $service->createQuote(
            $admin,
            null,
            ['customer_name' => 'Cliente Mostrador', 'customer_phone' => '5599-0000'],
            [
                ['product_id' => $products['BAT-12V-45']->id, 'quantity' => 1],
            ],
            5,
            'Cotización de batería',
        );
    }

    /**
     * @param  array<string, Product>  $products
     * @param  \Illuminate\Support\Collection<int, Customer>  $customers
     */
    private function seedOnlineOrders(array $products, \Illuminate\Support\Collection $customers): void
    {
        $service = app(OrderService::class);

        $order1 = $service->createOrder(
            [
                'customer_name' => $customers[1]->name,
                'customer_phone' => $customers[1]->phone,
                'customer_email' => $customers[1]->email,
                'customer_address' => $customers[1]->address,
                'delivery_type' => 'domicilio',
            ],
            [
                ['product_id' => $products['ACE-20W50-LT']->id, 'quantity' => 2],
                ['product_id' => $products['FIL-AIRE-001']->id, 'quantity' => 1],
            ],
            'Pedido realizado desde la tienda en línea',
        );
        $service->confirm($order1);
        $service->updateDeliveryStatus($order1, 'en_camino');

        $order2 = $service->createOrder(
            [
                'customer_name' => $customers[4]->name,
                'customer_phone' => $customers[4]->phone,
                'delivery_type' => 'recoger',
            ],
            [
                ['product_id' => $products['BUJ-STD-001']->id, 'quantity' => 4],
            ],
        );
        $service->cancel($order2, 'El cliente ya no lo necesitó');
    }
}
